public class ReferenceDemo {
    public static void main(String[] args) {
        // Reference type: Vehicle, Actual Object type: SportsCar
        Vehicle v = new SportsCar();

        // 1. Dynamic dispatch: executes SportsCar's start()
        v.start();

        // 2. Compile-time check fails if we uncomment:
        // v.turboBoost(); // Error: cannot find symbol turboBoost() in class Vehicle
    }
}

