abstract class Notification {
    public abstract void send(String msg);
}

class EmailNotification extends Notification {
    @Override
    public void send(String msg) {
        System.out.println("Emailing: " + msg);
    }
}

class SmsNotification extends Notification {
    @Override
    public void send(String msg) {
        System.out.println("SMS sending: " + msg);
    }
}

public class DispatchArrayDemo {
    public static void main(String[] args) {
        // Common reference type allows uniform array processing
        Notification[] channels = new Notification[] {
            new EmailNotification(),
            new SmsNotification()
        };

        for (Notification n : channels) {
            // Runtime actual object determines specific output
            n.send("System Maintenance at 2 AM");
        }
    }
}

