class MediaItem {
    protected String title;
    public MediaItem(String title) {
        this.title = title;
    }
    public void play() {
        System.out.println("Playing media: " + title);
    }
}

class AudioTrack extends MediaItem {
    private int bitrate;
    public AudioTrack(String title, int bitrate) {
        super(title);
        this.bitrate = bitrate;
    }
    @Override
    public void play() {
        System.out.println("Playing audio track: " + title + " @ " + bitrate + "kbps");
    }
}

class VideoTrack extends MediaItem {
    private String resolution;
    public VideoTrack(String title, String resolution) {
        super(title);
        this.resolution = resolution;
    }
    @Override
    public void play() {
        System.out.println("Streaming video: " + title + " in " + resolution);
    }
}

public class MediaApp {
    public static void main(String[] args) {
        MediaItem[] playlist = new MediaItem[] {
            new AudioTrack("Podcast Ep 1", 320),
            new VideoTrack("Nature Doc", "4K UHD")
        };
        for (MediaItem item : playlist) {
            item.play();
        }
    }
}

interface CloudResource {
    String getId();
    double getUtilization();
}

class ComputeInstance implements CloudResource {
    private String id;
    private double cpuPercent;
    public ComputeInstance(String id, double cpuPercent) {
        this.id = id;
        this.cpuPercent = cpuPercent;
    }
    @Override
    public String getId() { return id; }
    @Override
    public double getUtilization() { return cpuPercent; }
}

class StorageBucket implements CloudResource {
    private String id;
    private double usedGb;
    private double totalGb;
    public StorageBucket(String id, double usedGb, double totalGb) {
        this.id = id;
        this.usedGb = usedGb;
        this.totalGb = totalGb;
    }
    @Override
    public String getId() { return id; }
    @Override
    public double getUtilization() { return (usedGb / totalGb) * 100.0; }
}

class ClusterMonitor {
    public static void printReport(CloudResource resource) {
        System.out.println("Resource [" + resource.getId() + "] Utilization: " + resource.getUtilization() + "%");
    }
}

public class CloudApp {
    public static void main(String[] args) {
        CloudResource vm = new ComputeInstance("vm-web-01", 78.5);
        CloudResource storage = new StorageBucket("s3-assets", 400.0, 1000.0);
        ClusterMonitor.printReport(vm);
        ClusterMonitor.printReport(storage);
    }
}

