class Document {
    protected String content;
    public Document(String content) {
        this.content = content;
    }
    public Document copy() {
        return new Document(this.content);
    }
    public void display() {
        System.out.println("Document: " + content);
    }
}

class Spreadsheet extends Document {
    public Spreadsheet(String content) {
        super(content);
    }
    @Override
    public Spreadsheet copy() {
        return new Spreadsheet(this.content + " [GRID]");
    }
    @Override
    public void display() {
        System.out.println("Spreadsheet: " + content);
    }
}

public class PrototypeApp {
    public static void main(String[] args) {
        Document docRef = new Spreadsheet("Q3 Revenue");
        Document duplicate = docRef.copy();
        duplicate.display();
    }
}
